import{_ as a,o as r,c as s,a2 as t}from"./chunks/framework.D66Xq0Kv.js";const g=JSON.parse('{"title":"The program graph","description":"","frontmatter":{},"headers":[],"relativePath":"architecture/program-graph.md","filePath":"architecture/program-graph.md"}'),o={name:"architecture/program-graph.md"};function n(i,e,l,h,d,c){return r(),s("div",null,[...e[0]||(e[0]=[t('<h1 id="the-program-graph" tabindex="-1">The program graph <a class="header-anchor" href="#the-program-graph" aria-label="Permalink to &quot;The program graph&quot;">​</a></h1><p>The program graph is the union of several analyses over one IR:</p><ul><li><strong>Def-use chains</strong> resolve where every value is produced and consumed.</li><li><strong>Call graph</strong> drives interprocedural reachability and summaries.</li><li><strong>Points-to</strong> is Steensgaard-based with two-phase constraint solving; the second phase adds call-site-sensitive flow for sharper alias answers.</li><li><strong>Heap model + memory SSA</strong> model stores and loads so field-sensitive and index-sensitive flows (e.g. <code>$row[$col]</code>) participate in analysis.</li><li><strong>SVFG</strong> (Sparse Value-Flow Graph) connects value definitions to their uses across procedures, the substrate taint queries walk.</li></ul><h2 id="branch-sharpening" tabindex="-1">Branch sharpening <a class="header-anchor" href="#branch-sharpening" aria-label="Permalink to &quot;Branch sharpening&quot;">​</a></h2><p>Guards are not just cut-edges. Inside <code>if x &lt; 10 { ... }</code> the value lattice knows <code>x ∈ [.., 9]</code>; inside the else-branch it knows the negation. This makes range guards (<code>if i &lt; arr.len()</code>) <em>provably</em> dominate sinks instead of being matched textually.</p>',5)])])}const m=a(o,[["render",n]]);export{g as __pageData,m as default};
